// Synthetic 8×8 image with fictional camera metadata. No personal data.
const SAMPLE =
  "";
export function createSampleFile(): File {
  const bytes = Uint8Array.from(atob(SAMPLE), (character) =>
    character.charCodeAt(0),
  );
  return new File([bytes], "metastrip-sample.jpg", { type: "image/jpeg" });
}
